var sb = new System.Text.StringBuilder();
foreach (var bc in UnityEngine.Object.FindObjectsByType<BoxCollider>(FindObjectsInactive.Include, FindObjectsSortMode.None))
{
    var s = bc.transform.lossyScale;
    if (s.x < 0 || s.y < 0 || s.z < 0)
    {
        var t = bc.transform;
        sb.AppendLine($"BoxCollider on '{bc.gameObject.name}' (instanceID={bc.gameObject.GetInstanceID()})");
        var cur = t;
        while (cur != null)
        {
            sb.AppendLine($"  - {cur.name} (id={cur.gameObject.GetInstanceID()}) localScale={cur.localScale}");
            cur = cur.parent;
        }
    }
}
return sb.ToString();
